  "view_hash": "4bcf3592862da0a54863f5491341867f563e6ea45b47337c5c4286fa0d0a001f",
  "fim_base": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_04054cfee1",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada termina em D10; o calendário identifica D0 e usa dias corridos.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "Não há decisão sobre o aceite do laudo; sem aceite, duração e custo de readequação não foram definidos.",
      "A ficha relacional que contém precedências e requisitos de disponibilidade é mencionada, mas suas relações não estão disponíveis nesta view."
    ],
    "motivo": "A disponibilidade do substituto em D6 não determina, por si só, o término final. Sem aceite técnico e sem as relações de precedência disponíveis, não se pode calcular o cronograma nem sustentar uma direção de variação.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "O término novo não pode ser calculado, portanto faltam a magnitude e a direção da variação."
    ],
    "motivo": "Embora a linha base seja D10, os dados disponíveis não determinam o término após o aviso.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "O orçamento de referência fixo é R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A magnitude total depende do término final, pois há cobrança por extensão além de D10 e o término novo é indeterminado."
    ],
    "motivo": "A troca gera cobrança adicional de R$ 200,00 não incluída na linha base; não há crédito por antecipação, e pode haver cobrança adicional se o marco ultrapassar D10.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A magnitude do aumento não pode ser calculada sem determinar se haverá extensão além de D10."
    ],
    "motivo": "O aviso adiciona uma cobrança certa de R$ 200,00, sem crédito compensatório; eventual extensão pode aumentar ainda mais o custo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base é D10 e R$ 5.000,00. O aviso garante uma cobrança adicional de R$ 200,00, mas o término e os custos de eventual readequação ou extensão não podem ser calculados com as relações e decisões técnicas disponíveis."
}

